/** @purpose Shared domain types for todos and CLI commands. */

export interface Todo {
  id: number;
  title: string;
  completed: boolean;
  due?: string; // ISO date, e.g. "2026-11-01"
}

export type Command =
  | { kind: "add"; title: string; due?: string }
  | { kind: "complete"; id: number }
  | { kind: "list" };

export function nextId(todos: Todo[]): number {
  return todos.reduce((max, t) => Math.max(max, t.id), 0) + 1;
}

import { describe, expect, it } from "vitest";
import { nextId } from "./types";

describe("nextId", () => {
  it("starts at 1", () => expect(nextId([])).toBe(1));
  it("is one past the max id", () => {
    expect(nextId([{ id: 3, title: "a", completed: false }, { id: 7, title: "b", completed: true }])).toBe(8);
  });
});

/** @purpose Render todos as human-readable terminal text. */
import type { Todo } from "./types";

export function formatTodo(todo: Todo): string {
  const box = todo.completed ? "[x]" : "[ ]";
  return `${box} ${todo.title}`;
}

export function formatList(todos: Todo[]): string {
  if (todos.length === 0) return "No todos.";
  return todos.map(formatTodo).join("\n");
}

import { describe, expect, it } from "vitest";
import { formatList, formatTodo } from "./format";

describe("format", () => {
  it("formats open and done todos", () => {
    expect(formatTodo({ id: 1, title: "milk", completed: false })).toBe("[ ] milk");
    expect(formatTodo({ id: 2, title: "eggs", completed: true })).toBe("[x] eggs");
  });
  it("handles an empty list", () => expect(formatList([])).toBe("No todos."));
});

